pub(crate) fn preview_rend(state: &CombatState, card: &Card, target: Option<CreatureUid>) -> i32 {
    let debuffs: usize = target
        .and_then(|t| state.creatures.iter().find(|c| c.id == t.0))
        .map_or(0, |c| {
            c.powers
                .iter()
                .filter_map(|p_uid| state.powers.get_by_id(p_uid.0))
                .filter(|p| {
                    sts2_core::afflictions::is_debuff_for_amount(p.kind, p.amount)
                        && !sts2_core::afflictions::is_temporary_power_debuff(p.kind)
                })
                .count()
        });
    // v0.111.0: CalculationBase 15 -> 10, upgrade +3 -> +2 (decomp Rend.cs:19,40).
    let calc_base = match (
        crate::cards::v0111::is_v0111(state.game_version),
        card.upgraded,
    ) {
        (false, false) => 15,
        (false, true) => 18,
        (true, false) => 10,
        (true, true) => 12,
    };
    let extra = if card.upgraded { 8 } else { 5 };
    calc_base + extra * i32::try_from(debuffs).unwrap_or(i32::MAX)
}

